<div class="intro-line"><p>RAT dan angka usaha dicatat per tahun buku. Volume usaha baru masuk rekap setelah dokumen pendukung diperiksa dan laporan diverifikasi petugas.</p><?php if ($cooperative_id && $can_create): ?><a class="button button-dark" href="<?= site_url('admin/laporan-tahunan/tambah/'.$cooperative_id) ?>">+ Tambah laporan</a><?php elseif ($can_create): ?><a class="button button-quiet" href="<?= site_url('admin/koperasi') ?>">Pilih koperasi →</a><?php endif; ?></div>
<section class="panel table-panel"><form class="filterbar" method="get" action="<?= site_url($path) ?>"><?php if ($cooperative_id): ?><input type="hidden" name="cooperative_id" value="<?= $cooperative_id ?>"><?php endif; ?><label class="search-field"><span>Cari laporan</span><input type="search" name="q" value="<?= h($p['q']) ?>" placeholder="Koperasi, NIK, tahun"></label><label><span>Status</span><select name="status"><option value="">Semua</option><?php foreach ($statuses as $code=>$label): ?><option value="<?= h($code) ?>" <?= $p['status']===$code?'selected':'' ?>><?= h($label) ?></option><?php endforeach; ?></select></label><label><span>Per halaman</span><select name="per_page"><?php foreach (array(10,25,50,100) as $n): ?><option value="<?= $n ?>" <?= $p['per_page']===$n?'selected':'' ?>><?= $n ?></option><?php endforeach; ?></select></label><button class="button button-dark button-small">Terapkan</button><a class="button button-quiet button-small" href="<?= site_url($path).($cooperative_id?'?cooperative_id='.$cooperative_id:'') ?>">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Koperasi</th><th>Tahun buku</th><th>Volume usaha</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($rows as $report): ?><tr><td><strong><?= h($report['cooperative_name']) ?></strong><small class="cell-sub mono"><?= h($report['nik']) ?></small></td><td><?= h($report['fiscal_year']) ?></td><td><?= h(money_id($report['business_volume'])) ?></td><td><span class="pill <?= $report['verification_status']==='verified'?'pill-green':($report['verification_status']==='submitted'?'pill-blue':'pill-muted') ?>"><?= h($statuses[$report['verification_status']]??$report['verification_status']) ?></span></td><td><a class="row-link" href="<?= site_url('admin/laporan-tahunan/'.$report['id']) ?>">Buka →</a></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="5" class="empty-cell">Belum ada laporan yang sesuai filter.</td></tr><?php endif; ?></tbody></table></div><?php $this->load->view('partials/pagination'); ?></section>
